210  M3Result  ParseSection_Export  (IM3Module io_module, bytes_t i_bytes, cbytes_t  i_end)
   211  {
   212      M3Result result = m3Err_none;
   213
   214      u32 numExports;
   215  _   (ReadLEB_u32 (& numExports, & i_bytes, i_end));                                 m3log (parse, "** Export [%d]", numExports);
   216
   217      for (u32 i = 0; i < numExports; ++i)
   218      {
   219          const char * utf8;
   220          u8 exportKind;
   221          u32 index;
   222
   223  _       (Read_utf8 (& utf8, & i_bytes, i_end));
   224  _       (Read_u8 (& exportKind, & i_bytes, i_end));
   225  _       (ReadLEB_u32 (& index, & i_bytes, i_end));                                  m3log (parse, "    index: %3d; kind: %d; export: '%s'; ", index, (u32) exportKind, utf8);
   226
   227          if (exportKind == d_externalKind_function)
   228          {
   229              _throwif(m3Err_wasmMalformed, index >= io_module->numFunctions);
   230              u16 numNames = io_module->functions [index].numNames;
   231              if (numNames < d_m3MaxDuplicateFunctionImpl)
   232              {
   233                  io_module->functions [index].numNames++;
   234                  io_module->functions [index].names[numNames] = utf8;
   235                  utf8 = NULL; // ownership transferred to M3Function
   300      io_module->elementSectionEnd = i_end;
   301      io_module->numElementSegments = numSegments;
   302
   303      _catch: return result;
   304  }
