    12  void Module_FreeFunctions (IM3Module i_module)
    13  {
    14      for (u32 i = 0; i < i_module->numFunctions; ++i)
    15      {
    16          IM3Function func = & i_module->functions [i];
    17          Function_Release (func);
    18      }
    19  }
