    45  M3Result  Module_AddGlobal  (IM3Module io_module, IM3Global * o_global, u8 i_type, bool i_mutable, bool i_isImported)
    46  {
    47      M3Result result = m3Err_none;
    48  _try {
    49      u32 index = io_module->numGlobals++;
    50      io_module->globals = m3_ReallocArray (M3Global, io_module->globals, io_module->numGlobals, index);
    51      _throwifnull(io_module->globals);
    52      M3Global * global = & io_module->globals [index];
    53
    54      global->type = i_type;
    55      global->imported = i_isImported;
    56      global->isMutable = i_mutable;
    57
    58      if (o_global)
    59          * o_global = global;
    60
    61  } _catch:
    62      return result;
    63  }
