    66  M3Result  Module_AddFunction  (IM3Module io_module, u32 i_typeIndex, IM3ImportInfo i_importInfo)
    67  {
    68      M3Result result = m3Err_none;
    69
    70  _try {
    71      u32 index = io_module->numFunctions++;
    72      io_module->functions = m3_ReallocArray (M3Function, io_module->functions, io_module->numFunctions, index);
    73      _throwifnull(io_module->functions);
    74      _throwif("type sig index out of bounds", i_typeIndex >= io_module->numFuncTypes);
    75
    76      IM3FuncType ft = io_module->funcTypes [i_typeIndex];
    77
    78      IM3Function func = Module_GetFunction (io_module, index);
    79      func->funcType = ft;
    80  #if d_m3EnableStrace >= 2
    81      func->index = index;
    82  #endif
    83
    84      if (i_importInfo and func->numNames == 0)
    85      {
    86          func->import = * i_importInfo;
    87          func->numNames = 1;
    88          func->names[0] = i_importInfo->fieldUtf8;
    89      }
    90
    91      m3log (module, "   added function: %3d; sig: %d", index, i_typeIndex);
    92
    93  } _catch:
    94      return result;
    95  }
